const queue = global.get("parat_bridge.queue.entry_queue") || [];

queue.push({
    entry: msg.entry,
    _retries: 0
});

global.set("parat_bridge.queue.entry_queue", queue);
return msg;

const connection_name = msg.entry.metadata.connection_name;
const targetId = msg.entry.metadata.target && msg.entry.metadata.target.identifier;

// Remove the delivered entry from the queue
const queue = global.get("parat_bridge.queue.entry_queue") || [];
global.set("parat_bridge.queue.entry_queue", queue.filter(i => i.entry.id !== msg.entry.id));

// Release the connection slot
const in_flight = global.get("parat_bridge.queue.in_flight_connections") || [];
global.set("parat_bridge.queue.in_flight_connections", in_flight.filter(c => c !== connection_name));

// Fjern entry fra failed_entries hvis den lå der
if (connection_name && targetId) {
    const connections = global.get('parat_bridge.connections') || {};
    const conn = connections[connection_name];
    if (conn && conn.failed_entries && conn.failed_entries[targetId]) {
        const before = conn.failed_entries[targetId].length;
        conn.failed_entries[targetId] = conn.failed_entries[targetId]
            .filter(e => e.id !== msg.entry.id);
        if (conn.failed_entries[targetId].length !== before) {
            global.set('parat_bridge.connections.' + connection_name, conn);
        }
    }

    // Recovery: sjekk om dette er siste recovery-melding → send ✅
    if (msg.entry._recovery === true && conn) {
        conn._recovery_context = conn._recovery_context || {};
        const ctx = conn._recovery_context[targetId];
        if (ctx) {
            ctx.delivered = (ctx.delivered || 0) + 1;
            if (ctx.delivered >= ctx.total) {
                const entryQueue = global.get('parat_bridge.queue.entry_queue') || [];
                const now = Date.now();

                // ✅ til mottaker
                const currentTarget = conn.clients && conn.clients[targetId];
                if (currentTarget) {
                    entryQueue.push({
                        entry: {
                            id: 'pb-err-' + now + '-restored-' + Math.random().toString(36).slice(2, 5),
                            text: '✅ Tilkoblingen er gjenopprettet. Vanlig meldingsflyt er gjenopptatt.',
                            timestamp: now,
                            author: 'System-melding',
                            files: [],
                            labels: [],
                            metadata: {
                                source: { client_system: 'parat_bridge', name: 'parat_bridge', identifier: 'parat_bridge' },
                                target: currentTarget,
                                connection_name: connection_name
                            }
                        },
                        _retries: 0
                    });
                }

                // ✅ til avsendere
                const senderClients = Object.values(conn.clients || {}).filter(c => c.identifier !== targetId);
                senderClients.forEach((senderClient, sIdx) => {
                    entryQueue.push({
                        entry: {
                            id: 'pb-err-' + (now + 1 + sIdx) + '-sender-restored-' + Math.random().toString(36).slice(2, 5),
                            text: '✅ Tilkoblingen er gjenopprettet. Meldingene dine er nå levert.',
                            timestamp: now + 1 + sIdx,
                            author: 'System-melding',
                            files: [],
                            labels: [],
                            metadata: {
                                source: { client_system: 'parat_bridge', name: 'parat_bridge', identifier: 'parat_bridge' },
                                target: senderClient,
                                connection_name: connection_name
                            }
                        },
                        _retries: 0
                    });
                });

                global.set('parat_bridge.queue.entry_queue', entryQueue);

                // Rydd opp recovery-kontekst
                delete conn._recovery_context[targetId];
                conn.status = conn.status || {};
                conn.status.failed_clients = (conn.status.failed_clients || []).filter(id => id !== targetId);
                node.log('Recovery complete for ' + targetId + ': ✅ notifications sent');
            }
            global.set('parat_bridge.connections.' + connection_name, conn);
        }
    }
}

return msg;

const queue     = global.get("parat_bridge.queue.entry_queue") || [];
let   in_flight = global.get("parat_bridge.queue.in_flight_connections") || [];

// Prune stale in-flight slots — remove any connection with no entries left in the queue
in_flight = in_flight.filter(connection_name =>
    queue.some(i => i.entry.metadata.connection_name === connection_name)
);

// Find and claim the first sendable entry per connection
const to_send = [];

queue.forEach(i => {
    const connection_name = i.entry.metadata.connection_name;
    if (in_flight.includes(connection_name)) return;
    to_send.push({ ...msg, entry: i.entry });
    in_flight.push(connection_name);    
});

if (to_send.length === 0) {
    global.set("parat_bridge.queue.in_flight_connections", in_flight);
    return null;
}

global.set("parat_bridge.queue.in_flight_connections", in_flight);
return [to_send];

const MAX_RETRIES = 10;
const connection_name = msg.entry.metadata.connection_name;
const queue = global.get("parat_bridge.queue.entry_queue") || [];
const in_flight = global.get("parat_bridge.queue.in_flight_connections") || [];
const item = queue.find(i => i.entry.id === msg.entry.id);
// Helper — releases the connection slot
const release_slot = () =>
    in_flight.filter(c => c !== connection_name);
// Entry no longer in queue — release slot and trigger send to continue
if (!item) {
    global.set("parat_bridge.queue.in_flight_connections", release_slot());
    return [null, msg];
}
item._retries++;
// Max retries reached — drop all entries for this connection, release slot
if (item._retries > MAX_RETRIES) {
    // Before dropping: rescue any _recovery entries back to failed_entries.
    const recoveryEntries = queue.filter(i =>
        i.entry.metadata &&
        i.entry.metadata.connection_name === connection_name &&
        i.entry._recovery === true
    );
    if (recoveryEntries.length > 0) {
        const connections = global.get('parat_bridge.connections') || {};
        const conn = connections[connection_name];
        if (conn) {
            conn.failed_entries = conn.failed_entries || {};
            conn.status = conn.status || {};
            conn.status.failed_clients = conn.status.failed_clients || [];
            conn._recovery_context = conn._recovery_context || {};
            recoveryEntries.forEach(({ entry: rEntry }) => {
                const tId = rEntry.metadata &&
                    rEntry.metadata.target &&
                    rEntry.metadata.target.identifier;
                if (!tId) return;
                conn.failed_entries[tId] = conn.failed_entries[tId] || [];
                const toSave = { ...rEntry };
                delete toSave._recovery;
                if (!conn.failed_entries[tId].some(e => e.id === toSave.id)) {
                    conn.failed_entries[tId].push(toSave);
                }
                if (!conn.status.failed_clients.includes(tId)) {
                    conn.status.failed_clients.push(tId);
                }
                delete conn._recovery_context[tId];
            });
            global.set('parat_bridge.connections', connections);
            node.warn('MAX_RETRIES: rescued ' + recoveryEntries.length +
                ' recovery entries back to failed_entries for ' + connection_name);
        }
    }
    node.warn("Max retries reached — dropping all queued entries for connection: " + connection_name);
    global.set("parat_bridge.queue.entry_queue",
        queue.filter(i => i.entry.metadata.connection_name !== connection_name)
    );
    global.set("parat_bridge.queue.in_flight_connections", release_slot());
    return [msg, msg];
}
// Still within retry limit — release slot so send node re-picks this entry naturally
node.log("Retrying entry " + msg.entry.id + " (attempt " + item._retries + " of " + MAX_RETRIES + ")");
global.set("parat_bridge.queue.entry_queue", queue);
global.set("parat_bridge.queue.in_flight_connections", release_slot());
return [null, msg];

const entry = msg.entry;
const metadata = entry && entry.metadata;
const connection_name = metadata && metadata.connection_name;

const connections = global.get('parat_bridge.connections') || {};

const toCheck = connection_name
    ? (connections[connection_name] ? { [connection_name]: connections[connection_name] } : {})
    : connections;

const entryQueue = global.get('parat_bridge.queue.entry_queue') || [];
const cb = global.get('parat_bridge.circuit_breaker') || {};
let anyChange = false;

Object.entries(toCheck).forEach(([connName, conn]) => {
    if (!conn || !conn.active) return;

    const failedEntries = conn.failed_entries || {};
    const targetIds = Object.keys(failedEntries).filter(id =>
        Array.isArray(failedEntries[id]) && failedEntries[id].length > 0
    );
    if (targetIds.length === 0) return;

    conn._recovery_context = conn._recovery_context || {};

    targetIds.forEach((targetId, idx) => {
        // Ikke start ny recovery hvis det allerede er aktive recovery-entries i køen
        const activeRecovery = entryQueue.some(e =>
            e.entry._recovery === true &&
            e.entry.metadata &&
            e.entry.metadata.connection_name === connName &&
            e.entry.metadata.target &&
            e.entry.metadata.target.identifier === targetId
        );
        if (activeRecovery) {
            node.log('Recovery already in progress for ' + targetId + ', skipping');
            return;
        }

        // Kombiner failed_entries med meldinger som fremdeles retrier i køen
        const failedOnly = failedEntries[targetId];
        const pendingInQueue = entryQueue.filter(e =>
            e.entry.metadata &&
            e.entry.metadata.connection_name === connName &&
            e.entry.metadata.target &&
            e.entry.metadata.target.identifier === targetId &&
            !(e.entry.id && e.entry.id.startsWith('pb-err-')) &&
            !e.entry._recovery
        );
        const entries = [
            ...failedOnly,
            ...pendingInQueue.map(e => e.entry)
        ];
        if (entries.length === 0) return;

        // Fjern queue-stragglerne (de blir re-køet som recovery)
        const straggleIds = new Set(pendingInQueue.map(e => e.entry.id));
        for (let i = entryQueue.length - 1; i >= 0; i--) {
            if (straggleIds.has(entryQueue[i].entry.id)) entryQueue.splice(i, 1);
        }

        const currentTarget = conn.clients[targetId];
        if (!currentTarget) return;

        const base = Date.now() + idx * 10;

        // ⚠️ til mottaker
        entryQueue.push({
            entry: {
                id: 'pb-err-' + base + '-broken-' + Math.random().toString(36).slice(2, 5),
                text: '⚠️ Tilkoblingen ble brutt. Følgende ' + entries.length + ' melding(er) er ettersendt:',
                timestamp: base,
                author: 'System-melding',
                files: [],
                labels: [],
                metadata: {
                    source: { client_system: 'parat_bridge', name: 'parat_bridge', identifier: 'parat_bridge' },
                    target: currentTarget,
                    connection_name: connName
                }
            },
            _retries: 0
        });

        // Tapte meldinger, merket med _recovery: true
        entries.forEach(e => {
            entryQueue.push({
                entry: { ...e, _recovery: true, metadata: { ...e.metadata, target: currentTarget } },
                _retries: 0
            });
        });

        // Lagre recovery-kontekst (✅ sendes når alle er levert av Dequeue successful post)
        conn._recovery_context[targetId] = { total: entries.length, delivered: 0 };
        conn.failed_entries[targetId] = [];
        conn.status.failed_clients = (conn.status.failed_clients || []).filter(id => id !== targetId);
        delete cb[connName + '::' + targetId];
        node.log('Recovery: re-queued ' + entries.length + ' entries for ' + targetId + ' in ' + connName);
        anyChange = true;
    });
});

if (anyChange) {
    global.set('parat_bridge.queue.entry_queue', entryQueue);
    global.set('parat_bridge.connections', connections);
    global.set('parat_bridge.circuit_breaker', cb);
}

return null;
